    slug: "2026-05-20-pre-execution-authority-gates",
    title: "Pre-Execution Authority Gates: Why Governance Must Be Evaluated Before State Mutation",
    date: "2026-05-20",
    timestamp: "07:00 AM PT",
    type: EntryType.ShortEssay,
